        /// <summary>The table for a language code, or null when it is not compiled in.</summary>
        public static Dictionary<string, string> For(string code)
        {
            switch (code)
            {
                case "en": return En;
                case "it": return It;
                case "zh": return Zh;
                default: return null;
            }
        }
    }
